def transform(grid):
    from collections import Counter, defaultdict, deque

    h, w = len(grid), len(grid[0])
    counts = Counter(v for row in grid for v in row)
    bg = counts.most_common(1)[0][0]
    wall = next((v for v, _ in counts.most_common() if v != bg), bg)

    seen = [[False] * w for _ in range(h)]
    out = [row[:] for row in grid]

    for sr in range(h):
        for sc in range(w):
            if seen[sr][sc] or grid[sr][sc] == wall:
                continue

            q = deque([(sr, sc)])
            seen[sr][sc] = True
            cells = []
            while q:
                r, c = q.popleft()
                cells.append((r, c))
                for nr, nc in ((r-1,c), (r+1,c), (r,c-1), (r,c+1)):
                    if (0 <= nr < h and 0 <= nc < w and not seen[nr][nc]
                            and grid[nr][nc] != wall):
                        seen[nr][nc] = True
                        q.append((nr, nc))

            top = min(r for r, c in cells)
            bottom = max(r for r, c in cells)
            left = min(c for r, c in cells)
            right = max(c for r, c in cells)

            seeds = defaultdict(list)
            for r, c in cells:
                color = grid[r][c]
                if color != bg:
                    d = min(r-top, bottom-r, c-left, right-c)
                    seeds[d].append(color)

            if not seeds:
                continue

            # A lone seed on the outermost ring colors the whole chamber.
            if len(seeds) == 1 and 0 in seeds:
                color = seeds[0][0]
                for r, c in cells:
                    out[r][c] = color
                continue

            depth_colors = {d: colors[0] for d, colors in seeds.items()}
            for r, c in cells:
                d = min(r-top, bottom-r, c-left, right-c)
                if d in depth_colors:
                    out[r][c] = depth_colors[d]
                else:
                    candidates = [sd for sd in depth_colors if sd > 0 and (d-sd) % 2 == 0]
                    if candidates:
                        sd = min(candidates, key=lambda x: abs(x-d))
                        out[r][c] = depth_colors[sd]
                    else:
                        out[r][c] = bg

    return out
