def transform(grid):
    from collections import defaultdict

    h, w = len(grid), len(grid[0])
    bg = max(set(v for row in grid for v in row),
             key=lambda x: sum(v == x for row in grid for v in row))
    # Divider color is the most frequent non-background color.
    freq = {}
    for row in grid:
        for v in row:
            if v != bg:
                freq[v] = freq.get(v, 0) + 1
    wall = max(freq, key=freq.get)

    hlines = [r for r in range(h) if wall in grid[r]]
    vlines = [c for c in range(w) if any(grid[r][c] == wall for r in range(h))]
    out = [row[:] for row in grid]
    rooms = defaultdict(list)

    def room_for(r, c):
        tops = [0] + [y + 1 for y in hlines if y < r]
        bottoms = [h - 1] + [y - 1 for y in hlines if y > r]
        lefts = [0] + [x + 1 for x in vlines if x < c]
        rights = [w - 1] + [x - 1 for x in vlines if x > c]
        choices = []
        for top in tops:
            for bottom in bottoms:
                if top > r or bottom < r or top > bottom:
                    continue
                for left in lefts:
                    for right in rights:
                        if left > c or right < c or left > right:
                            continue
                        # Each interior boundary must have divider cells on it.
                        if top > 0 and not any(grid[top-1][x] == wall for x in range(left, right+1)):
                            continue
                        if bottom < h-1 and not any(grid[bottom+1][x] == wall for x in range(left, right+1)):
                            continue
                        if left > 0 and not any(grid[y][left-1] == wall for y in range(top, bottom+1)):
                            continue
                        if right < w-1 and not any(grid[y][right+1] == wall for y in range(top, bottom+1)):
                            continue
                        area = (bottom-top+1)*(right-left+1)
                        choices.append((area, top, bottom, left, right))
        if choices:
            _, top, bottom, left, right = min(choices)
            return top, bottom, left, right
        return 0, h-1, 0, w-1

    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color != bg and color != wall:
                box = room_for(r, c)
                top, bottom, left, right = box
                depth = min(r-top, bottom-r, c-left, right-c)
                rooms[box].append((depth, color))

    for (top, bottom, left, right), seeds in rooms.items():
        by_depth = {}
        for d, color in seeds:
            by_depth[d] = color
        depths = sorted(by_depth)
        colors = [by_depth[d] for d in depths]

        for r in range(top, bottom+1):
            for c in range(left, right+1):
                if grid[r][c] == wall:
                    continue
                d = min(r-top, bottom-r, c-left, right-c)
                if len(colors) == 1:
                    sd = depths[0]
                    out[r][c] = colors[0] if (d-sd) % 2 == 0 else bg
                else:
                    out[r][c] = colors[(d-depths[0]) % len(colors)]
    return out
